<?php require_once 'config.php';require_login();verify_csrf();if(current_user()['role']!=='trainee'){flash('Only trainee accounts can enroll in courses.','error');redirect('courses.php');}$id=(int)($_POST['course_id']??0);$s=db()->prepare("SELECT id FROM courses WHERE id=? AND status='published'");$s->execute([$id]);if(!$s->fetch()){flash('That course is not available.','error');redirect('courses.php');}try{$s=db()->prepare('INSERT INTO enrollments(user_id,course_id) VALUES(?,?)');$s->execute([current_user()['id'],$id]);flash('You are enrolled! Your learning journey starts now.');}catch(PDOException $e){flash('You are already enrolled in this course.','error');}redirect('course.php?id='.$id);
